import{z as s,x as p,o as i,c as B,q as r,j as t,D as e,d as o,s as A,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"NoPE","description":"","frontmatter":{"title":"NoPE","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/nope.md","filePath":"llm/nope.md","lastUpdated":1791413859000}'),d={name:"llm/nope.md"};function P(m,a,h,D,N,u){const l=p("Mermaid");return i(),B("div",null,[a[2]||(a[2]=r('<h1 id="nope" tabindex="-1">NoPE <a class="header-anchor" href="#nope" aria-label="Permalink to &quot;NoPE&quot;">​</a></h1><div class="epigraph"><p>在解码器里拿掉显式位置编码，因果掩码仍能提供顺序；长度外推上，这种「什么都不加」有时反而更好。</p><footer>—— Kazemnejad 等，位置编码与长度泛化，2023</footer></div><p><a href="/llm/position-extrapolation">上一课</a>把朴素 RoPE 外推的典型失败写成相位超出训练弧长，位置插值把下标按 \\(L/L&#39;\\) 压回原窗口，代价是高频局部分辨率下降，补丁越来越复杂。缺口是把问题倒过来：解码器若删掉显式位置，只留因果掩码，顺序还在不在，长度泛化会不会因此变好？Kazemnejad 等人 2023 年的 NoPE 表明：能，而且在若干外推设定里可以优于常见显式方案。本课写「无位置」并非无顺序，不重列插值与 NTK 的补丁菜单；显式通道有时会变成过拟合训练长度的捷径。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>编码器的自注意力双向可见，置换等变，没有位置就无法区分「A 在 B 前」与相反。解码器不同：第 \\(i\\) 个位置只能看见 \\(0\\) 到 \\(i\\)，可见集合的大小恰好是 \\(i+1\\)。理论上，网络可以通过「我能看见多少东西」恢复自己的下标，通过「你比我少看多少」恢复相对距离。显式位置编码不是唯一的顺序来源。</p><p>实践里显式编码很强，因为它们把下标变成容易线性读出的特征，训练损失下降更快。代价在长度泛化：RoPE 的相位、绝对嵌入的表、甚至 ALiBi 的斜率，都会把「训练长度」写进归纳偏置。模型可能用这些特征记忆「第 512 个位置附近该怎么做」，而不是用内容与可见范围计算。一旦序列更长，捷径失效。问题是：在解码器里删除显式位置，强迫计算走因果掩码这条对长度更不变的路，外推会不会更好？<span class="marginnote">NoPE 的赌注不是「语言没有顺序」，而是「顺序已经在掩码的可见性里」。显式通道若与训练长度绑定过紧，会在外推时变成负担而不是帮助。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>NoPE 的实现几乎是否定句：词嵌入之后不加算术位置、不旋转 \\(Q\\) 与 \\(K\\)、不加距离偏置。注意力就是缩放点积加因果下三角掩码。其余与普通 Pre-LN 解码器相同。</p><p>训练仍在固定或有上界的长度上进行，因为批次要切分。与 ALiBi 的「训短测长」不同，NoPE 并不在 logits 上写距离；它依赖层叠的因果注意力自己构造位置敏感的电路。Kazemnejad 等人在受控长度泛化任务与 Transformer 语言模型上比较绝对、相对、RoPE、ALiBi 与 NoPE，观察哪一种在超出训练长度时掉点更慢。</p><p><span class="marginnote">直觉类比：不报数也能知道自己是第几个——数一数前面排了几个人就行。因果掩码让每个 token 恰好能「数出」前面的队伍长度，这就是没有显式位置编码时顺序仍然在的来源。</span></p>',10)),(i(),t(n,null,{default:e(()=>[A(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E8%AF%8D%E5%B5%8C%E5%85%A5%22%5D%20--%3E%20A%5B%22%E5%9B%A0%E6%9E%9C%E8%87%AA%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A%20%20M%5B%22%E4%B8%8B%E4%B8%89%E8%A7%92%E5%8F%AF%E8%A7%81%E6%8E%A9%E7%A0%81%22%5D%20--%3E%20A%0A%20%20A%20--%3E%20F%5B%22%E5%89%8D%E9%A6%88%E5%B1%82%22%5D%0A%20%20F%20--%3E%20O%5B%22%E4%B8%8B%E4%B8%80%E5%B1%82%22%5D%0A%20%20N%5B%22%E6%97%A0%E4%BD%8D%E7%BD%AE%E5%90%91%E9%87%8F%22%5D%20-.-%3E%20E%0A%20%20N%20-.-%3E%20A%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"方法贡献主要在实验设计：把位置方案换成可插拔模块，长度作为独立轴，而不是只报训练窗口内的困惑度。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[o("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("h3",{id:"因果掩码如何泄漏位置",tabindex:"-1"},[o("因果掩码如何泄漏位置 "),E("a",{class:"header-anchor",href:"#因果掩码如何泄漏位置","aria-label":'Permalink to "因果掩码如何泄漏位置"'},"​")],-1)),a[6]||(a[6]=E("p",null,"第 \\(i\\) 个查询的注意力归一化是在 \\(i+1\\) 个键上做的。softmax 的配分函数、均值、极值统计都随 \\(i\\) 变化。多层之后，表示可以编码「当前可见前缀有多长」。相对位置则可通过「键侧表示已经过多少次只能看见更短前缀的变换」来区分：更早的 token 经过更多步的「被后续位置读取」。这不是闭式的 \\(i-j\\)，而是一种可学习的深度计数。",-1)),(i(),t(n,null,{default:e(()=>[A(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20ENC%5B%22%E5%8F%8C%E5%90%91%E7%BC%96%E7%A0%81%E5%99%A8%22%5D%20--%3E%7C%22%E6%AF%8F%E4%B8%AA%E4%BD%8D%E7%BD%AE%E5%8F%AF%E8%A7%81%E5%85%A8%E4%BD%93%22%7C%20SAME%5B%22%E5%8F%AF%E8%A7%81%E9%9B%86%E5%90%88%E7%9B%B8%E5%90%8C%20%E9%A1%BA%E5%BA%8F%E4%B8%8D%E5%8F%AF%E8%BE%A8%22%5D%0A%20%20DEC%5B%22%E5%9B%A0%E6%9E%9C%E8%A7%A3%E7%A0%81%E5%99%A8%22%5D%20--%3E%7C%22%E7%AC%AC%20i%20%E4%BD%8D%E5%8F%AA%E5%8F%AF%E8%A7%81%E5%89%8D%20i%2B1%20%E4%B8%AA%22%7C%20DIFF%5B%22%E5%8F%AF%E8%A7%81%E6%95%B0%E9%87%8F%E6%81%B0%E5%A5%BD%E7%AD%89%E4%BA%8E%E4%B8%8B%E6%A0%87%22%5D%0A%20%20SAME%20--%3E%20LOST%5B%22%E5%88%A0%E6%8E%89%E4%BD%8D%E7%BD%AE%E7%BC%96%E7%A0%81%20%E9%A1%BA%E5%BA%8F%E4%B8%A2%E5%A4%B1%22%5D%0A%20%20DIFF%20--%3E%20LEAK%5B%22%E5%88%A0%E6%8E%89%E4%BD%8D%E7%BD%AE%E7%BC%96%E7%A0%81%20%E9%A1%BA%E5%BA%8F%E4%BB%8D%E4%BB%8E%E8%AE%A1%E6%95%B0%E6%B3%84%E6%BC%8F%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p>这张图回答「为什么只有解码器敢删位置编码」：双向注意力里所有位置可见集合一样大，删掉显式位置就真瞎；因果掩码让可见集合的大小恰好等于下标，顺序从「我能看见多少」这个侧信道泄漏出来。</p><p>因此 NoPE 仍有位置信息，只是位置被藏在计算图的非对称里，而不是藏在加性向量或旋转角里。读出它需要深度与注意力头的配合，浅模型或头数不足时，可能学不全计数电路，这时显式编码会重新显得必要。</p><h3 id="长度外推为何有时更好" tabindex="-1">长度外推为何有时更好 <a class="header-anchor" href="#长度外推为何有时更好" aria-label="Permalink to &quot;长度外推为何有时更好&quot;">​</a></h3><p>显式编码给出与 \\(L_{\\text{train}}\\) 绑定的坐标系。RoPE 在 \\(L\\) 附近有一套被拟合的相位用法；绝对嵌入在最后若干行上有一套被拟合的向量。外推时坐标系的新点没有训练监督。NoPE 的坐标系是「可见集合的基数」，基数在更长序列上只是继续增大，没有未见过的嵌入行，也没有未见过的旋转角。若任务的算法本身是「对前缀做内容选择」，这种计数可以延续。</p><p><span class="marginnote">数字实例：RoPE 训练到 4096，位置 5000 的旋转角训练时从没出现过——像只背过 4096 级以内的阶梯，第 5000 级踩空。NoPE 的「可见数 = 5000」只是把同一个计数继续往上数，没有一行没见过的嵌入、一个没见过的相位。</span></p><p><span class="marginnote">「有时更好」不能写成「总是更好」。语言建模在训练长度内，RoPE 或 ALiBi 通常仍更省参数、更易优化。NoPE 的优势集中在长度泛化轴上，而且依赖足够深度去构造位置电路。浅解码器去掉位置后，连训练窗口内都可能不稳。</span></p><h3 id="与-alibi、rope-的取舍" tabindex="-1">与 ALiBi、RoPE 的取舍 <a class="header-anchor" href="#与-alibi、rope-的取舍" aria-label="Permalink to &quot;与 ALiBi、RoPE 的取舍&quot;">​</a></h3><p>ALiBi 也走「不把下标写成向量」的路，但在 logits 上留下单调距离势，近邻优先被硬编码。NoPE 连这势都没有，近邻优势必须由内容与深度自己学。对自然语言，近邻优先往往是正确偏置，ALiBi 更省事；对需要把位置当计数器、且测试比训练长得多的算法任务，硬编码势可能反而限制电路形状。RoPE 则把相对位置写进几何，训练内最强，外推最依赖插值或改基数——那是位置插值与 YaRN 的问题，不是 NoPE 要修的。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>NoPE 几乎不被用于从零训练的超大通用语言模型：在固定上下文里，显式相对位置的样本效率更高，业界默认 RoPE。它的价值是揭示位置通道与长度过拟合的关系，以及在需要外推的解码器实验里提供一条强基线。</p><p>实现上仍要处理批次填充：因果掩码必须把 pad 排除，否则「可见长度」变成「含 pad 的长度」，位置电路被污染。这比有显式位置时更致命，因为模型没有另一套下标可以对照。</p><p><span class="marginnote">常见误区：以为 NoPE「什么都不加」就没有位置层面的 bug。填充没掩干净时，「可见长度」混入 pad 的数量，位置计数直接算错——显式模型还有第二套下标可对照，NoPE 的这套计数是唯一真相，一错无处兜底。</span></p><p><span class="marginnote">推理期把 NoPE 模型接到长于训练的窗口，没有 RoPE 那种相位爆炸，但不保证质量。没有距离势时，注意力更容易在长前缀上摊平或被句首吸走。长度外推「有时更好」来自受控实验，不是生产模型的默认承诺。</span></p><h3 id="何时值得当真尝试" tabindex="-1">何时值得当真尝试 <a class="header-anchor" href="#何时值得当真尝试" aria-label="Permalink to &quot;何时值得当真尝试&quot;">​</a></h3><p>合成长度泛化、需要把位置当指针的程序式任务、以及研究「位置编码是否在帮倒忙」的消融——这些场合 NoPE 是一等公民。通用聊天模型的长窗口，优先仍是 RoPE 加插值或 YaRN，或从零用 ALiBi。不要把 NoPE 理解成可以省掉位置模块就省参数的免费午餐：省掉的是参数，买到的是更难优化的位置电路。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NoPE 指解码器不添加位置嵌入、旋转或距离偏置，只保留因果掩码。</li><li>可见前缀长度与层叠读取提供可学习的位置信息，因此「无位置」并非无顺序。</li><li>在 Kazemnejad 等人的长度泛化设定里，NoPE 有时优于绝对、RoPE 与 ALiBi。</li><li>训练窗口内的样本效率通常仍低于显式相对位置，大模型默认不会只用 NoPE。</li><li>填充掩码必须干净，否则可见长度被 pad 污染，位置电路失效。</li><li>它说明显式位置可能成为长度捷径；外推问题有时该做减法而不是更复杂的插值。</li><li>出处：Kazemnejad 等，关于解码器位置编码与长度泛化的研究，2023；对照 Press 等 ALiBi（2021）与 Vaswani 等原 Transformer 的位置需求（编码器侧，2017）。</li></ul>',17))])}const b=s(d,[["render",P]]);export{F as __pageData,b as default};
